34	const PROCESSING_FEE = 5;
35	
36	const FIRST_INSURANCE_SURCHARGE = 0.1;
37	
38	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
39	  sword: 100,
40	  amulet: 60,
41	};
42	
43	const quotePremium = (step: QuoteStep): number => {
44	  const policyBase = step.items.reduce(
45	    (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type],
46	    0,
47	  );
48	  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
49	};
50	
51	export const runScenario = (scenario: Scenario): ScenarioResult => ({
52	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
53	});
