const basePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const quotePremium = (step: QuoteStep): number => {
  const policyBase = step.items.reduce(
    (sum, item) => sum + basePremium(item),
    0,
  );
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE;
  return policyBase + firstInsuranceSurcharge + PROCESSING_FEE;
};
